$shared = @()
foreach ($si in $sharedXml.SelectNodes('//a:si', $ns)) {
  $texts = $si.SelectNodes('.//a:t', $ns) | ForEach-Object { $_.'#text' }
  $shared += ,(($texts -join ''))
}
function Get-CellValue($cell) {
  $type = $cell.t
  $v = $cell.v
  if ($null -eq $v) { return '' }
  if ($type -eq 's') { return $shared[[int]$v] }
  return [string]$v
}
function Show-Sheet($sheetFile, $label, $maxRows=6) {
  [xml]$sheetXml = Get-Content "$base\worksheets\$sheetFile"
  $sheetNs = New-Object System.Xml.XmlNamespaceManager($sheetXml.NameTable)
  $sheetNs.AddNamespace('a','http://schemas.openxmlformats.org/spreadsheetml/2006/main')
  Write-Output ("SHEET: $label")
  $rows = $sheetXml.SelectNodes('//a:sheetData/a:row', $sheetNs)
  $count = [Math]::Min($maxRows, $rows.Count)
  for ($i = 0; $i -lt $count; $i++) {
    $row = $rows[$i]
    $vals = @()
    foreach ($cell in $row.SelectNodes('./a:c', $sheetNs)) {
      $vals += (Get-CellValue $cell)
    }
    Write-Output ('ROW ' + $row.r + ': ' + ($vals -join ' | '))
  }
  Write-Output '---'
}
