import React, { useEffect, useState } from "react";
import DealsKanban from "./components/DealsKanban";
import vairtexLogo from "./assets/vairtex-logo.png";

const API_BASE_URL = "http://localhost:3000";
const BRAND = {
  name: "VairTEX CRM",
