      setDeals(previousDeals);
      setErrorMessage(error.message);
    } finally {
      setSavingDealId(null);
    }
  }

  function handleContactFormChange(event) {
    const { name, value } = event.target;
    setContactForm((current) => ({ ...current, [name]: value }));
