          title: contactForm.title
        })
      });

      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.error || "Failed to create contact");
      }

      setContacts((current) => [...current, data]);
      setContactForm((current) => ({
        ...current,
        first_name: "",
        last_name: "",
        email: "",
        title: ""
      }));
      setSuccessMessage(`Contact "${data.first_name} ${data.last_name}" created.`);
    } catch (error) {
      setErrorMessage(error.message);
    }
  }

  async function handleCreateCompany(event) {
    event.preventDefault();
    setErrorMessage("");
    setSuccessMessage("");

    try {
      const response = await fetch(`${API_BASE_URL}/companies`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(companyForm)
      });

      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.error || "Failed to create company");
      }

      setCompanies((current) => [...current, data]);
      setCompanyForm({
        name: "",
        industry: "",
        location: "",
        work_phone: "",
        assignee: ""
      });
      setSuccessMessage(`Company "${data.name}" created.`);
    } catch (error) {
      setErrorMessage(error.message);
    }
  }

  async function handleCreateDeal(event) {
    event.preventDefault();
    setErrorMessage("");
    setSuccessMessage("");

    try {
      const response = await fetch(`${API_BASE_URL}/deals`, {
        method: "POST",
