    transition: "background 0.2s ease, border-color 0.2s ease"
  },
  columnActive: {
    background: "#e8f3ea",
    borderColor: "#7da487"
  },
  columnHeader: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    marginBottom: "12px"
  },
  columnTitle: {
