    padding: "12px",
    marginBottom: "10px"
  },
  cardDragging: {
    boxShadow: "0 12px 24px rgba(57, 45, 22, 0.18)"
  },
  cardTitle: {
    margin: "0 0 8px",
    fontSize: "0.98rem",
